<?php $page_title='Masuk';include 'partials/header.php';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){$email=trim($_POST['email']);$pw=$_POST['password'];$st=$conn->prepare('SELECT * FROM users WHERE email=?');$st->bind_param('s',$email);$st->execute();$u=$st->get_result()->fetch_assoc();if($u && password_verify($pw,$u['password'])){$_SESSION['user']=['id'=>$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>$u['role']];header('Location: '.($u['role']==='admin'?'admin/index.php':'index.php'));exit;}else $err='Email atau password salah.';}?><section class="auth panel"><h2>Selamat Datang</h2><?php if(isset($_GET['registered'])):?><div class="alert success">Pendaftaran berhasil, silakan login.</div><?php endif;?><?php if($err):?><div class="alert"><?=$err?></div><?php endif;?><form method="post"><div class="form-group"><label>Email</label><input class="input" type="email" name="email" required></div><div class="form-group"><label>Password</label><input class="input" type="password" name="password" required></div><button class="btn" style="width:100%">Masuk</button></form><p class="muted" style="font-size:12px">Admin demo: admin@shopverse.test / <b>admin123</b></p><p class="muted" style="text-align:center">Belum punya akun? <a href="register.php">Daftar</a></p></section><?php include 'partials/footer.php';?>
